/**
 * src/javascript/code-nodes/*.js を workflows/*.json の Code ノード (jsCode) へ埋め込む。
 *
 * 対象: jsCode の 1 行目が `// @source <repo相対パス>` で始まる n8n-nodes-base.code ノード。
 * ソースは CommonJS で `module.exports.run(items)` を公開していること。
 */

const SOURCE_MARKER = /^\/\/ @source (\S+)/;
const CODE_NODE_TYPE = 'n8n-nodes-base.code';

function getSourcePath(jsCode) {
  if (typeof jsCode !== 'string') return null;
  const match = jsCode.match(SOURCE_MARKER);
  return match ? match[1] : null;
}

function buildNodeCode(sourcePath, sourceCode) {
  return [
    `// @source ${sourcePath}`,
    '// AUTO-GENERATED by `npm run sync:code`. Edit the source file above, not this node.',
    'const module = { exports: {} };',
    'const exports = module.exports;',
    sourceCode.trimEnd(),
    'return module.exports.run($input.all());',
    '',
  ].join('\n');
}

/**
 * @param {object} workflow パース済みワークフロー（破壊的に更新する）
 * @param {(path: string) => string} readSource リポジトリ相対パスからソースを読む関数
 * @returns {{ name: string, source: string }[]} 内容が変化したノード
 */
function syncWorkflow(workflow, readSource) {
  const changed = [];
  for (const node of workflow.nodes || []) {
    if (node.type !== CODE_NODE_TYPE || !node.parameters) continue;
    const sourcePath = getSourcePath(node.parameters.jsCode);
    if (!sourcePath) continue;
    const next = buildNodeCode(sourcePath, readSource(sourcePath));
    if (next !== node.parameters.jsCode) {
      node.parameters.jsCode = next;
      changed.push({ name: node.name, source: sourcePath });
    }
  }
  return changed;
}

module.exports = { getSourcePath, buildNodeCode, syncWorkflow };
